17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
32	import org.springframework.samples.petclinic.rest.api.OwnersApi;
33	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
34	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
35	import org.springframework.samples.petclinic.rest.dto.PetDto;
36	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
39	import org.springframework.samples.petclinic.service.ClinicService;
40	import org.springframework.samples.petclinic.util.TelephoneNormalizer;
41	import org.springframework.security.access.prepost.PreAuthorize;
42	import org.springframework.web.bind.annotation.CrossOrigin;
43	import org.springframework.web.bind.annotation.RequestMapping;
44	import org.springframework.web.bind.annotation.RestController;
45	import org.springframework.web.util.UriComponentsBuilder;
46	
47	import jakarta.transaction.Transactional;
48	
49	/**
50	 * @author Vitaliy Fedoriv
51	 */
52	
53	@RestController
54	@CrossOrigin(exposedHeaders = "errors, content-type")
55	@RequestMapping("/api")
56	public class OwnerRestControllerV1 implements OwnersApi {
57	
58	    private final ClinicService clinicService;
59	
60	    private final OwnerMapper ownerMapper;
61	
62	    private final PetMapper petMapper;
63	
64	    private final VisitMapper visitMapper;
65	
66	    private final TelephoneNormalizer telephoneNormalizer;
67	
68	    public OwnerRestControllerV1(ClinicService clinicService,
69	                                 OwnerMapper ownerMapper,
70	                                 PetMapper petMapper,
71	                                 VisitMapper visitMapper,
72	                                 TelephoneNormalizer telephoneNormalizer) {
73	        this.clinicService = clinicService;
74	        this.ownerMapper = ownerMapper;
75	        this.petMapper = petMapper;
76	        this.visitMapper = visitMapper;
77	        this.telephoneNormalizer = telephoneNormalizer;
78	    }
79	
80	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
81	    @Override
82	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
83	        Collection<Owner> owners;
84	        if (lastName != null) {
85	            owners = this.clinicService.findOwnerByLastName(lastName);
86	        } else {
87	            owners = this.clinicService.findAllOwners();
88	        }
89	        if (owners.isEmpty()) {
90	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
91	        }
92	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
93	    }
94	
95	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
96	    @Override
97	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
98	        Owner owner = this.clinicService.findOwnerById(ownerId);
99	        if (owner == null) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
108	        HttpHeaders headers = new HttpHeaders();
109	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
110	        // Normalize the telephone on create so it is stored and returned in canonical form.
111	        // Bean validation on OwnerFieldsDto has already guaranteed a well-formed value
112	        // (rejecting anything else with 400).
113	        String normalizedTelephone = telephoneNormalizer.normalize(owner.getTelephone());
114	        owner.setTelephone(normalizedTelephone);
115	        // Store the (already syntactically validated) email lower-cased so it is persisted and
116	        // returned in canonical form. A missing email is left untouched.
117	        owner.setEmail(normalizeEmail(owner.getEmail()));
118	        // Default the registration date to the server's current date when the client did not
119	        // supply one, so it is persisted and returned in ISO 'YYYY-MM-DD' form.
120	        if (owner.getRegistrationDate() == null) {
121	            owner.setRegistrationDate(java.time.LocalDate.now());
122	        }
123	        // Reject creating an owner whose normalized telephone is already used by another owner.
124	        if (isTelephoneInUse(normalizedTelephone)) {
125	            throw new DuplicateTelephoneException(
126	                "An owner with telephone " + normalizedTelephone + " already exists");
127	        }
128	        this.clinicService.saveOwner(owner);
129	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
130	        headers.setLocation(UriComponentsBuilder.newInstance()
131	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
132	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
133	    }
134	
135	    /**
136	     * Lower-cases the supplied email address so it is stored and returned in canonical form.
137	     * Bean validation on the request DTO has already guaranteed that any non-null value is a
138	     * syntactically valid address (rejecting anything else with 400).
139	     *
140	     * @param email the email value (may be {@code null})
141	     * @return the lower-cased email, or {@code null} if the input was {@code null}
142	     */
143	    private String normalizeEmail(String email) {
144	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
145	    }
146	
147	    /**
148	     * Determines whether the given normalized telephone is already used by an existing owner.
149	     * Stored telephones are normalized before comparison so values that differ only in
150	     * formatting (spaces, dashes, parentheses) are treated as the same number.
151	     *
152	     * @param normalizedTelephone the normalized (digits-only) telephone to look for
153	     * @return {@code true} if another owner already uses this telephone
154	     */
155	    private boolean isTelephoneInUse(String normalizedTelephone) {
156	        if (normalizedTelephone == null) {
157	            return false;
158	        }
159	        return this.clinicService.findAllOwners().stream()
160	            .map(Owner::getTelephone)
161	            .map(telephoneNormalizer::normalize)
162	            .anyMatch(normalizedTelephone::equals);
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Override
167	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
168	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
169	        if (currentOwner == null) {
170	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
171	        }
172	        currentOwner.setAddress(ownerFieldsDto.getAddress());
173	        currentOwner.setCity(ownerFieldsDto.getCity());
174	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
175	        currentOwner.setLastName(ownerFieldsDto.getLastName());
176	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
177	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
178	        this.clinicService.saveOwner(currentOwner);
179	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
180	    }
181	
182	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
183	    @Transactional
184	    @Override
185	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
186	        Owner owner = this.clinicService.findOwnerById(ownerId);
187	        if (owner == null) {
188	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
189	        }
190	        this.clinicService.deleteOwner(owner);
191	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
192	    }
193	
194	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
195	    @Override
196	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
197	        Owner owner = this.clinicService.findOwnerById(ownerId);
198	        if (owner == null) {
199	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
200	        }
201	        HttpHeaders headers = new HttpHeaders();
202	        Pet pet = petMapper.toPet(petFieldsDto);
203	        owner.setId(ownerId);
